(* [comment removed for export] *)
Definition w4s31_ctx (RNG : footprint) (mm : amem) (P DT4 DBL DBH DST dcap tl mtl SEG SS n SBL SBH S1 C3 : Z)
    (cells : list deltX1) : Prop :=
  w4s1_dctx RNG mm P DT4 DBL DBH DST dcap tl /\
  bytes_at asegs mm DT4 (firstn (Z.to_nat (2 * 2^tl)) (x1_bytes cells)) /\
  w4s_src_ctx RNG mm SS n SBL SBH /\
  rw_cells asegs mm (P + 176) [C8 (Z_to_bv 64 (S1 + 8))] /\ rw_cells asegs mm (P + 216) [C8 (Z_to_bv 64 C3)] /\
  rw_cells asegs mm (P + 136) [C8 (Z_to_bv 64 2147450880)] /\
  rw_cells asegs mm (P + 208) [C8 (Z_to_bv 64 (DST + SEG))] /\
  rw_cells asegs mm (P + 104) [C8 (Z_to_bv 64 (tl + 256 * mtl))] /\
  rw_cells asegs mm (P + 24) [C8 (Z_to_bv 64 DST)] /\ rw_cells asegs mm (P + 96) [C8 (Z_to_bv 64 SEG)].

Lemma w4s31_ctx_tr : forall RNG mm mm' P DT4 DBL DBH DST dcap tl mtl SEG SS n SBL SBH S1 C3 cells W,
  w4s31_ctx RNG mm P DT4 DBL DBH DST dcap tl mtl SEG SS n SBL SBH S1 C3 cells ->
  munch W mm mm' -> wmono asegs mm mm' -> mem_inv asegs mm' -> x1_table_ok cells tl ->
  disjoint_from W (shad DBL) (shad (DBH - 1) + 1 - shad DBL) ->
  disjoint_from W (shad DST) (shad (DST + dcap - 1) + 1 - shad DST) ->
  disjoint_from W SS n -> disjoint_from W (shad SBL) (shad (SBH - 1) + 1 - shad SBL) ->
  disjoint_from W DT4 (2 * 2^tl) ->
  disjoint_from W (P + 176) 8 -> disjoint_from W (P + 216) 8 -> disjoint_from W (P + 136) 8 ->
  disjoint_from W (P + 208) 8 -> disjoint_from W (P + 104) 8 -> disjoint_from W (P + 24) 8 -> disjoint_from W (P + 96) 8 ->
