(* [comment removed for export] *)
Lemma w4s31_DL : forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
    (x1 gp tp x6 x7 x8 x9 x11 x15 x16 x18 x19 x21 x23 x24 x25 x26 x28 x29 x30 x31 : word)
    (P DT4 DBL DBH DST dcap tl PP PE S1 BW : Z) (cells : list deltX1) (obuf : list Z) (cw : word),
  w4s1_dctx RNG mm P DT4 DBL DBH DST dcap tl -> mem_inv asegs mm ->
  x1_table_ok cells tl -> bytes_at asegs mm DT4 (firstn (Z.to_nat (2 * 2^tl)) (x1_bytes cells)) ->
  u8arr asegs mm DST (map (Z_to_bv 8) obuf) -> zlen obuf = dcap ->
  rw_cells asegs mm (P + 232) [C8 cw] -> rw_cells asegs mm (P + 136) [C8 (Z_to_bv 64 2147450880)] ->
  DST <= PP -> PP + 4 <= DST + dcap -> 0 <= BW <= 7 ->
  (forall (mm' : amem) (B' : Z) (y6 y11 y12 y28 y29 y30 y31 : word),
     munch [(DST, DST + dcap)] mm mm' -> wmono asegs mm mm' -> mem_inv asegs mm' ->
     (exists obuf', u8arr asegs mm' DST (map (Z_to_bv 8) obuf') /\ zlen obuf' = dcap) -> 0 <= B' <= 55 ->
     evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp (Z_to_bv 64 (64 - tl)) y6 x7 x8 x9 (Z_to_bv 64 (PP + 4)) y11 y12
                              (Z_to_bv 64 64) (Z_to_bv 64 (PP + 4)) x15 x16 (Z_to_bv 64 (PE + -3)) x18 x19 (Z_to_bv 64 S1) x21
                              (Z_to_bv 64 DT4) x23 x24 x25 x26 (Z_to_bv 64 B') y28 y29 y30 y31)
                         F (Z_to_bv 64 0x918c4) fc None mm' (seg_rom asegs))) ->
  evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp (Z_to_bv 64 (64 - tl)) x6 x7 x8 x9 (Z_to_bv 64 PP) x11 cw
                           (Z_to_bv 64 64) (Z_to_bv 64 PP) x15 x16 (Z_to_bv 64 (PE + -3)) x18 x19 (Z_to_bv 64 S1) x21
                           (Z_to_bv 64 DT4) x23 x24 x25 x26 (Z_to_bv 64 BW) x28 x29 x30 x31)
