(* [comment removed for export] *)
Lemma w4s31_loop : forall (fuel : nat) (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
    (x1 gp tp x6 x7 x8 x9 x11 x12 x15 x16 x18 x19 x21 x23 x24 x25 x28 x29 x30 x31 : word)
    (P DT4 DBL DBH DST dcap tl mtl SEG SS n SBL SBH S1 L1 PTR BITS PP C3 : Z) (cells : list deltX1) (obuf : list Z)
    (w232 : word),
  DST + SEG - PP <= 4 * Z.of_nat fuel ->
  w4s31_ctx RNG mm P DT4 DBL DBH DST dcap tl mtl SEG SS n SBL SBH S1 C3 cells -> mem_inv asegs mm ->
  x1_table_ok cells tl -> u8arr asegs mm DST (map (Z_to_bv 8) obuf) -> zlen obuf = dcap ->
  rw_cells asegs mm (P + 232) [C8 w232] ->
  n < 2^26 -> KXGoM.apart SS n P 496 -> KXGoM.apart DST dcap SS n -> 1 <= n ->
  SS <= S1 -> S1 + L1 <= SS + n -> 8 <= S1 -> S1 + 16 <= 2^47 ->
  S1 <= PTR -> (PTR = S1 \/ PTR + 8 <= S1 + L1) -> 0 <= BITS <= 64 ->
  DST <= PP -> PP <= DST + SEG -> DST + 4 <= DST + SEG -> DST + SEG <= DST + dcap -> DST + dcap < 2^47 -> 0 <= C3 < 2^64 ->
  (forall (mm' : amem) (PP' B' : Z) (cw y6 y10 y12 y28 y29 y30 y31 : word),
     munch [(DST, DST + dcap); (P + 232, P + 240)] mm mm' -> wmono asegs mm mm' -> mem_inv asegs mm' ->
     (exists obuf', u8arr asegs mm' DST (map (Z_to_bv 8) obuf') /\ zlen obuf' = dcap) ->
     rw_cells asegs mm' (P + 232) [C8 cw] -> 0 <= B' <= 64 -> DST <= PP' <= DST + SEG ->
     w4s31_ctx RNG mm' P DT4 DBL DBH DST dcap tl mtl SEG SS n SBL SBH S1 C3 cells ->
     evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp (Z_to_bv 64 (64 - tl)) y6 x7 x8 x9 y10 (Z_to_bv 64 PP') y12
                              (Z_to_bv 64 64) (Z_to_bv 64 PP') x15 x16 (Z_to_bv 64 (DST + SEG + -3)) x18 x19 (Z_to_bv 64 S1) x21
                              (Z_to_bv 64 DT4) x23 x24 x25 (Z_to_bv 64 C3) (Z_to_bv 64 B') y28 y29 y30 y31)
                         F (Z_to_bv 64 0x91d88) fc None mm' (seg_rom asegs))) ->
  evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp (Z_to_bv 64 (64 - tl)) x6 x7 x8 x9 (Z_to_bv 64 PP) x11 x12
                           (Z_to_bv 64 64) (Z_to_bv 64 PP) x15 x16 (Z_to_bv 64 (DST + SEG + -3)) x18 x19 (Z_to_bv 64 S1) x21
                           (Z_to_bv 64 DT4) x23 x24 x25 (Z_to_bv 64 PTR) (Z_to_bv 64 BITS) x28 x29 x30 x31)
